20	NS_CC_BEGIN
21	
22	namespace
23	{
24	    // ContactInfo::contactPoints and ::depths are fixed size arrays. Chipmunk never reports
25	    // more than CP_MAX_CONTACTS_PER_ARBITER (2) points per arbiter, so this is a hard bound.
26	    const int kMaxContactPoints = 4;
27	
28	    // init() reserves the contact cache up front, but a caller may pass a very large cap;
29	    // only this many slots are pre-allocated, the rest grow on demand.
30	    const size_t kMaxReservedContacts = 4096;
31	
32	    // The collision handler installed on a cpSpace stores a raw manager pointer and chipmunk
33	    // has no API to remove a default handler again, so every initialised manager is tracked
34	    // here and the handler thunks refuse to dereference a manager that is no longer live.
35	    std::vector<PhysicsContactManager*>& liveManagers()
36	    {
37	        static std::vector<PhysicsContactManager*> managers;
38	        return managers;
39	    }
40	
41	    bool isLiveManager(PhysicsContactManager* manager)
42	    {
43	        const std::vector<PhysicsContactManager*>& managers = liveManagers();
44	        return std::find(managers.begin(), managers.end(), manager) != managers.end();
45	    }
46	
47	    void registerManager(PhysicsContactManager* manager)
48	    {
49	        if (manager == nullptr || isLiveManager(manager))
50	        {
51	            return;
52	        }
53	
54	        liveManagers().push_back(manager);
55	    }
56	
57	    void unregisterManager(PhysicsContactManager* manager)
58	    {
59	        std::vector<PhysicsContactManager*>& managers = liveManagers();
60	        std::vector<PhysicsContactManager*>::iterator it = std::find(managers.begin(), managers.end(), manager);
61	        if (it != managers.end())
62	        {
63	            managers.erase(it);
64	        }
65	    }
66	
67	    PhysicsContactManager* managerFromData(cpDataPointer data)
68	    {
69	        PhysicsContactManager* manager = static_cast<PhysicsContactManager*>(data);
70	        return (manager != nullptr && isLiveManager(manager)) ? manager : nullptr;
71	    }
72	
73	    // The world's protected space member is not reachable here, so the space is taken from the
74	    // first body that is actually simulated. A world that is still empty resolves to nullptr,
75	    // which is why every caller re-resolves instead of caching the result once.
76	    cpSpace* resolveSpace(PhysicsWorld* world)
77	    {
78	        if (world == nullptr)
79	        {
80	            return nullptr;
81	        }
82	
83	        const Vector<PhysicsBody*>& bodies = world->getAllBodies();
84	        for (const auto& body : bodies)
85	        {
86	            if (body == nullptr)
87	            {
88	                continue;
89	            }
90	
91	            cpBody* rawBody = body->getCPBody();
92	            if (rawBody == nullptr)
93	            {
94	                continue;
95	            }
96	
97	            cpSpace* space = cpBodyGetSpace(rawBody);
98	            if (space != nullptr)
99	            {
100	                return space;
101	            }
102	        }
103	
104	        return nullptr;
105	    }
106	
107	    void resetContactInfo(ContactInfo& info)
108	    {
109	        info.shapeA = nullptr;
110	        info.shapeB = nullptr;
111	        for (int i = 0; i < kMaxContactPoints; ++i)
112	        {
113	            info.contactPoints[i] = Vec2::ZERO;
114	            info.depths[i] = 0.0f;
115	        }
116	        info.normal = Vec2::ZERO;
117	        info.pointCount = 0;
118	        info.totalImpulse = 0.0f;
119	        info.isNew = false;
120	        info.isPersistent = false;
121	    }
122	
123	    // Fills every field of info from the arbiter. Returns false when the arbiter does not map
124	    // onto a pair of cocos shapes, in which case info is left fully zeroed.
125	    bool buildContactInfo(cpArbiter* arbiter, ContactInfo& info)
126	    {
127	        resetContactInfo(info);
128	
129	        if (arbiter == nullptr)
130	        {
131	            return false;
132	        }
133	
134	        cpShape* rawShapeA = nullptr;
135	        cpShape* rawShapeB = nullptr;
136	        cpArbiterGetShapes(arbiter, &rawShapeA, &rawShapeB);
137	        if (rawShapeA == nullptr || rawShapeB == nullptr)
138	        {
139	            return false;
140	        }
141	
142	        PhysicsShape* shapeA = static_cast<PhysicsShape*>(cpShapeGetUserData(rawShapeA));
143	        PhysicsShape* shapeB = static_cast<PhysicsShape*>(cpShapeGetUserData(rawShapeB));
144	        if (shapeA == nullptr || shapeB == nullptr)
145	        {
146	            return false;
147	        }
148	
149	        info.shapeA = shapeA;
150	        info.shapeB = shapeB;
151	        info.normal = PhysicsHelper::cpv2point(cpArbiterGetNormal(arbiter));
152	
153	        // Zero during a separate callback, at most CP_MAX_CONTACTS_PER_ARBITER otherwise.
154	        int count = cpArbiterGetCount(arbiter);
155	        if (count < 0)
156	        {
157	            count = 0;
158	        }
159	        if (count > kMaxContactPoints)
160	        {
161	            count = kMaxContactPoints;
162	        }
163	
164	        for (int i = 0; i < count; ++i)
165	        {
166	            // The two surface points differ by the penetration, so the manifold point is
167	            // reported half way between them.
168	            Vec2 pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(arbiter, i));
169	            Vec2 pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(arbiter, i));
170	            info.contactPoints[i] = (pointA + pointB) * 0.5f;
171	
172	            // cpArbiterGetDepth() is a signed separation: negative while the shapes overlap.
173	            info.depths[i] = std::fabs(PhysicsHelper::cpfloat2float(cpArbiterGetDepth(arbiter, i)));
174	        }
175	
176	        info.pointCount = count;
177	        info.totalImpulse = PhysicsHelper::cpfloat2float(cpvlength(cpArbiterTotalImpulse(arbiter)));
178	        info.isNew = cpArbiterIsFirstContact(arbiter) != 0;
179	        info.isPersistent = !info.isNew && cpArbiterIsRemoval(arbiter) == 0;
180	
181	        return true;
182	    }
183	
184	    // The contactTest bitmasks decide whether a pair is *reported*; collision is decided by the
185	    // category/collision bitmasks in PhysicsContactManager::filterContact().
186	    bool shouldReportContact(PhysicsShape* shapeA, PhysicsShape* shapeB)
187	    {
188	        if (shapeA == nullptr || shapeB == nullptr)
189	        {
190	            return false;
191	        }
192	
193	        const int categoryA = shapeA->getCategoryBitmask();
194	        const int categoryB = shapeB->getCategoryBitmask();
195	        const int testA = shapeA->getContactTestBitmask();
196	        const int testB = shapeB->getContactTestBitmask();
197	
198	        return ((categoryA & testB) | (categoryB & testA)) != 0;
199	    }
200	
201	    // Invokes every callback in registration order. The loop is index based and re-reads the
202	    // container size, so a callback may register another callback without invalidating it.
203	    void invokeCallbacks(const std::vector<ContactCallbackFunc>& callbacks, const ContactInfo& info)
204	    {
205	        for (size_t i = 0; i < callbacks.size(); ++i)
206	        {
207	            ContactCallbackFunc callback = callbacks[i];
208	            if (callback)
209	            {
210	                callback(info);
211	            }
212	        }
213	    }
