399	PhysicsContactManager::~PhysicsContactManager()
400	{
401	    // Leaving the live registry is what makes the handler thunks safe: the cpSpace keeps the
402	    // raw manager pointer and chipmunk cannot restore its own default handler funcs.
403	    unregisterManager(this);
404	
405	    _contacts.clear();
406	    _beginCallbacks.clear();
407	    _preSolveCallbacks.clear();
408	    _postSolveCallbacks.clear();
409	    _separateCallbacks.clear();
410	    _customFilter = nullptr;
411	    _world = nullptr;
412	    _initialized = false;
413	}
