507	bool PhysicsContactManager::filterContact(PhysicsShape* shapeA, PhysicsShape* shapeB) const
508	{
509	    if (shapeA == nullptr || shapeB == nullptr || shapeA == shapeB)
510	    {
511	        return false;
512	    }
513	
514	    PhysicsBody* bodyA = shapeA->getBody();
515	    PhysicsBody* bodyB = shapeB->getBody();
516	    if (bodyA == nullptr || bodyB == nullptr || bodyA == bodyB)
517	    {
518	        // Two shapes of the same body never collide with each other.
519	        return false;
520	    }
521	
522	    const int groupA = shapeA->getGroup();
523	    const int groupB = shapeB->getGroup();
524	    if (groupA != 0 && groupA == groupB)
525	    {
526	        // Equal non-zero groups override the bitmasks: positive groups always collide,
527	        // negative groups never do.
528	        if (groupA < 0)
529	        {
530	            return false;
531	        }
532	    }
533	    else if ((shapeA->getCategoryBitmask() & shapeB->getCollisionBitmask()) == 0
534	             || (shapeB->getCategoryBitmask() & shapeA->getCollisionBitmask()) == 0)
535	    {
536	        return false;
537	    }
538	
539	    if (_customFilter)
540	    {
541	        // Only the pair is known at filtering time - the manifold is not solved yet - so the
542	        // custom filter receives a fully zeroed ContactInfo carrying just the two shapes.
543	        ContactInfo info;
544	        resetContactInfo(info);
545	        info.shapeA = shapeA;
546	        info.shapeB = shapeB;
547	
548	        if (!_customFilter(info))
549	        {
550	            return false;
551	        }
552	    }
553	
554	    return true;
555	}
