632	const ContactInfo* PhysicsContactManager::findContactBetween(PhysicsBody* bodyA, PhysicsBody* bodyB) const
633	{
634	    if (bodyA == nullptr || bodyB == nullptr)
635	    {
636	        return nullptr;
637	    }
638	
639	    for (size_t i = 0; i < _contacts.size(); ++i)
640	    {
641	        const ContactInfo& info = _contacts[i];
642	        if (info.shapeA == nullptr || info.shapeB == nullptr)
643	        {
644	            continue;
